//! Assemble a served zone: SOA/NS generated by the server, the tenant's records, and — for a
//! signed zone — DNSKEY/`CDS`/`CDNSKEY`, the NSEC chain and every `RRSIG`.
//!
//! This is a pure function of `(zone, identity, keys, now)`. Time is a parameter, never read
//! here, so expiry, refresh and rollover are testable with a synthetic clock.
//!
//! ## Signing layout
//!
//! * **KSK(s)** sign only the key `RRsets` (DNSKEY, CDS, CDNSKEY).
//! * The **active ZSK** signs every other `RRset`, including NSEC and the SOA.
//! * **Pre-publish ZSK rollover** (RFC 6781 §4.1.1.1): the next ZSK appears in the DNSKEY `RRset`
//!   `prepublish` seconds before it signs; the previous ZSK stays published for `retire_grace`
//!   after it stops signing so cached signatures remain verifiable. The schedule is a pure
//!   function of the registration's `origin`, so every node agrees without coordination.
//! * **KSK rollover** is the double-DS method (RFC 6781 §4.1.2): `ksk_next` publishes a second
//!   KSK; `CDS`/`CDNSKEY` list every published KSK, so a parent that polls CDS holds both DS
//!   records; once the parent DS TTL has passed the control plane promotes `ksk_next` to
//!   `ksk_gen`, the old KSK leaves the DNSKEY set and the CDS set, and the parent drops its DS.

use crate::keys::{KeyError, KeyProvider, KeyRole};
use crate::zone::{DnssecPolicy, Zone};
use hickory_proto::dnssec::rdata::{DNSSECRData, CDNSKEY, CDS, DNSKEY, NSEC, RRSIG};
use hickory_proto::dnssec::{
    Algorithm, DigestType, DnsSecResult, DnssecSigner, PublicKey, PublicKeyBuf, SigningKey, TBS,
};
use hickory_proto::rr::rdata::{NS, SOA};
use hickory_proto::rr::{DNSClass, Name, RData, Record, RecordSet, RecordType, RrKey};
use std::collections::{BTreeMap, BTreeSet};
use std::fmt;
use std::sync::Arc;
use std::time::Duration;
use time::OffsetDateTime;

/// Server-wide facts every generated SOA/NS uses.
#[derive(Debug, Clone)]
pub struct ServerIdentity {
    /// Our nameserver names (the NS set of every zone; first is the SOA MNAME).
    pub nameservers: Vec<Name>,
    /// SOA RNAME (hostmaster mailbox in DNS form).
    pub hostmaster: Name,
    /// SOA minimum = negative-cache TTL (RFC 2308).
    pub soa_minimum: u32,
    /// TTL of the apex NS `RRset`.
    pub ns_ttl: u32,
}

/// Signing / rollover timings, all in seconds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Timings {
    /// A ZSK generation signs for this long.
    pub zsk_period: u64,
    /// The next ZSK is published this long before it signs.
    pub prepublish: u64,
    /// A retired ZSK stays published this long after it stops signing.
    pub retire_grace: u64,
    /// Signature lifetime from "now".
    pub sig_validity: u64,
    /// Re-sign when fewer than this many seconds of validity remain.
    pub refresh_before: u64,
    /// Inception is back-dated by this much to tolerate validator clock skew.
    pub inception_skew: u64,
    /// TTL of the key `RRsets` (DNSKEY, CDS, CDNSKEY).
    pub key_ttl: u32,
    /// Highest TTL any `RRset` can carry (the tenant cap): bounds how long old signatures can live in caches.
    pub max_ttl: u32,
}

impl Default for Timings {
    fn default() -> Self {
        Timings {
            zsk_period: 30 * 86_400,
            prepublish: 2 * 86_400,
            retire_grace: 7 * 86_400,
            sig_validity: 5 * 86_400,
            refresh_before: 2 * 86_400,
            inception_skew: 3_600,
            key_ttl: 3_600,
            max_ttl: 86_400,
        }
    }
}

impl Timings {
    /// Check the relations a safe rollover and "refresh well inside expiry" need.
    pub fn validate(&self) -> Result<(), &'static str> {
        if self.sig_validity == 0 || self.zsk_period == 0 {
            return Err("zero period");
        }
        if self.refresh_before >= self.sig_validity
            || self.refresh_before.saturating_mul(3) < self.sig_validity
        {
            return Err("refresh_before must be in [validity/3, validity)");
        }
        if self.prepublish < u64::from(self.key_ttl).saturating_mul(2) {
            return Err("prepublish must be at least twice the key TTL");
        }
        if self.retire_grace < self.sig_validity + u64::from(self.max_ttl) {
            return Err("retire_grace must cover signature validity plus the maximum TTL");
        }
        if self.prepublish >= self.zsk_period {
            return Err("prepublish must be shorter than the ZSK period");
        }
        Ok(())
    }
}

/// Start of ZSK generation `g`.
fn zsk_start(p: &DnssecPolicy, t: &Timings, g: u32) -> u64 {
    p.origin
        .saturating_add(u64::from(g).saturating_mul(t.zsk_period))
}

/// The ZSK generation that signs at `now`.
#[must_use]
pub fn zsk_active(p: &DnssecPolicy, t: &Timings, now: u64) -> u32 {
    u32::try_from(now.saturating_sub(p.origin) / t.zsk_period).unwrap_or(u32::MAX)
}

/// The ZSK generations published in the DNSKEY `RRset` at `now`: the active one, the next one
/// from `prepublish` before it activates, and the previous one for `retire_grace` after it was
/// replaced.
#[must_use]
pub fn zsk_published(p: &DnssecPolicy, t: &Timings, now: u64) -> Vec<u32> {
    let active = zsk_active(p, t, now);
    let mut out = Vec::with_capacity(3);
    if let Some(prev) = active.checked_sub(1) {
        if now < zsk_start(p, t, active).saturating_add(t.retire_grace) {
            out.push(prev);
        }
    }
    out.push(active);
    if let Some(next) = active.checked_add(1) {
        if now.saturating_add(t.prepublish) >= zsk_start(p, t, next) {
            out.push(next);
        }
    }
    out
}

/// The next instant the published or signing key set changes (so a serving loop can rebuild
/// exactly then, not just at signature refresh).
#[must_use]
pub fn next_schedule_event(p: &DnssecPolicy, t: &Timings, now: u64) -> u64 {
    let active = zsk_active(p, t, now);
    let next_start = zsk_start(p, t, active.saturating_add(1));
    let mut ev = vec![next_start, next_start.saturating_sub(t.prepublish)];
    if active > 0 {
        ev.push(zsk_start(p, t, active).saturating_add(t.retire_grace));
    }
    ev.into_iter()
        .filter(|e| *e > now)
        .min()
        .unwrap_or(u64::MAX)
}

/// DS record data a parent should hold for one of our KSKs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DsData {
    /// Key tag.
    pub key_tag: u16,
    /// Algorithm number (13).
    pub algorithm: u8,
    /// Digest type (2 = SHA-256).
    pub digest_type: u8,
    /// The digest.
    pub digest: Vec<u8>,
}

impl fmt::Display for DsData {
    /// Presentation form a customer pastes into their registrar: `tag alg digtype HEXDIGEST`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{} {} {} ",
            self.key_tag, self.algorithm, self.digest_type
        )?;
        for b in &self.digest {
            write!(f, "{b:02X}")?;
        }
        Ok(())
    }
}

/// Why a zone could not be assembled.
#[derive(Debug)]
pub enum BuildError {
    /// The zone is signed but no key provider was supplied.
    KeysRequired,
    /// A key was unavailable.
    Key(KeyError),
    /// Signing or record assembly failed.
    Sign(String),
}

impl fmt::Display for BuildError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BuildError::KeysRequired => {
                f.write_str("zone requires DNSSEC but no key provider is configured")
            }
            BuildError::Key(e) => write!(f, "{e}"),
            BuildError::Sign(e) => write!(f, "signing failed: {e}"),
        }
    }
}

impl std::error::Error for BuildError {}

impl From<KeyError> for BuildError {
    fn from(e: KeyError) -> Self {
        BuildError::Key(e)
    }
}

fn sign_err(e: impl fmt::Display) -> BuildError {
    BuildError::Sign(e.to_string())
}

/// A fully assembled zone, ready to hand to the serving engine.
#[derive(Debug)]
pub struct SignedZone {
    /// The apex.
    pub origin: Name,
    /// Every `RRset`, with `RRSIGs` attached when signed.
    pub records: BTreeMap<RrKey, RecordSet>,
    /// SOA serial (the zone version).
    pub serial: u32,
    /// Whether the zone is DNSSEC-signed.
    pub signed: bool,
    /// When the serving loop must rebuild (signature refresh or key-schedule change).
    pub refresh_at: u64,
    /// Earliest `RRSIG` expiry (0 when unsigned).
    pub earliest_expiry: u64,
    /// DS records for the published KSKs (what the parent should hold).
    pub ds: Vec<DsData>,
}

/// Adapter so an `Arc<dyn SigningKey>` can be boxed into a hickory signer.
struct ArcKey(Arc<dyn SigningKey>);

impl SigningKey for ArcKey {
    fn sign(&self, tbs: &TBS) -> DnsSecResult<Vec<u8>> {
        self.0.sign(tbs)
    }
    fn to_public_key(&self) -> DnsSecResult<PublicKeyBuf> {
        self.0.to_public_key()
    }
    fn algorithm(&self) -> Algorithm {
        self.0.algorithm()
    }
}

struct Loaded {
    key: Arc<dyn SigningKey>,
    dnskey: DNSKEY,
}

fn load(
    provider: &dyn KeyProvider,
    zone: &Name,
    role: KeyRole,
    generation: u32,
) -> Result<Loaded, BuildError> {
    let key = provider.key(zone, role, generation)?;
    let pk = key.to_public_key().map_err(sign_err)?;
    let dnskey = DNSKEY::new(true, role == KeyRole::Ksk, false, pk);
    Ok(Loaded { key, dnskey })
}

fn signer_for(l: &Loaded, apex: &Name, duration: Duration) -> DnssecSigner {
    DnssecSigner::new(
        l.dnskey.clone(),
        Box::new(ArcKey(l.key.clone())),
        apex.clone(),
        duration,
    )
}

fn ds_of(apex: &Name, dnskey: &DNSKEY) -> Result<DsData, BuildError> {
    let digest = dnskey
        .to_digest(apex, DigestType::SHA256)
        .map_err(sign_err)?;
    Ok(DsData {
        key_tag: dnskey.calculate_key_tag().map_err(sign_err)?,
        algorithm: u8::from(Algorithm::ECDSAP256SHA256),
        digest_type: 2,
        digest: digest.as_ref().to_vec(),
    })
}

/// The DS set a parent should hold for `zone` at `now`: one per published KSK. This is what the
/// control plane shows the customer and what `DelegationCheck` compares the parent against.
pub fn expected_ds(
    apex: &Name,
    policy: &DnssecPolicy,
    provider: &dyn KeyProvider,
) -> Result<Vec<DsData>, BuildError> {
    let mut out = Vec::new();
    for g in ksk_generations(policy) {
        out.push(ds_of(apex, &load(provider, apex, KeyRole::Ksk, g)?.dnskey)?);
    }
    Ok(out)
}

fn ksk_generations(p: &DnssecPolicy) -> Vec<u32> {
    let mut v = vec![p.ksk_gen];
    if let Some(n) = p.ksk_next {
        if n != p.ksk_gen {
            v.push(n);
        }
    }
    v
}

fn add(sets: &mut BTreeMap<RrKey, RecordSet>, rec: Record, serial: u32) {
    let key = RrKey::new(rec.name.clone().into(), rec.record_type());
    sets.entry(key)
        .or_insert_with(|| RecordSet::new(rec.name.clone(), rec.record_type(), serial))
        .insert(rec, serial);
}

/// Build the served form of `zone` at `now`.
#[expect(
    clippy::too_many_lines,
    reason = "one linear sequence; splitting it would obscure the order of the steps"
)]
pub fn build_zone(
    zone: &Zone,
    id: &ServerIdentity,
    keys: Option<&dyn KeyProvider>,
    t: &Timings,
    now: u64,
) -> Result<SignedZone, BuildError> {
    let serial = u32::try_from(zone.version).unwrap_or(u32::MAX);
    let apex = &zone.apex;
    let mut sets: BTreeMap<RrKey, RecordSet> = BTreeMap::new();

    let mname = id
        .nameservers
        .first()
        .cloned()
        .unwrap_or_else(|| apex.clone());
    let soa = SOA::new(
        mname,
        id.hostmaster.clone(),
        serial,
        3_600,
        600,
        1_209_600,
        id.soa_minimum,
    );
    add(
        &mut sets,
        Record::from_rdata(apex.clone(), id.soa_minimum, RData::SOA(soa)),
        serial,
    );
    for ns in &id.nameservers {
        add(
            &mut sets,
            Record::from_rdata(apex.clone(), id.ns_ttl, RData::NS(NS(ns.clone()))),
            serial,
        );
    }
    for r in &zone.records {
        add(&mut sets, r.to_record(), serial);
    }

    let Some(policy) = zone.dnssec else {
        return Ok(SignedZone {
            origin: apex.clone(),
            records: sets,
            serial,
            signed: false,
            refresh_at: u64::MAX,
            earliest_expiry: 0,
            ds: Vec::new(),
        });
    };
    let provider = keys.ok_or(BuildError::KeysRequired)?;

    // keys
    let mut ksks = Vec::new();
    for g in ksk_generations(&policy) {
        ksks.push(load(provider, apex, KeyRole::Ksk, g)?);
    }
    let active_gen = zsk_active(&policy, t, now);
    let mut zsks = Vec::new();
    for g in zsk_published(&policy, t, now) {
        zsks.push((g, load(provider, apex, KeyRole::Zsk, g)?));
    }

    // key RRsets
    let mut ds = Vec::new();
    for l in ksks.iter().chain(zsks.iter().map(|(_, l)| l)) {
        add(
            &mut sets,
            Record::from_rdata(
                apex.clone(),
                t.key_ttl,
                RData::DNSSEC(DNSSECRData::DNSKEY(l.dnskey.clone())),
            ),
            serial,
        );
    }
    for l in &ksks {
        let d = ds_of(apex, &l.dnskey)?;
        add(
            &mut sets,
            Record::from_rdata(
                apex.clone(),
                t.key_ttl,
                RData::DNSSEC(DNSSECRData::CDS(CDS::new(
                    d.key_tag,
                    Some(Algorithm::ECDSAP256SHA256),
                    DigestType::SHA256,
                    d.digest.clone(),
                ))),
            ),
            serial,
        );
        add(
            &mut sets,
            Record::from_rdata(
                apex.clone(),
                t.key_ttl,
                RData::DNSSEC(DNSSECRData::CDNSKEY(CDNSKEY::new(
                    true,
                    true,
                    false,
                    Some(Algorithm::ECDSAP256SHA256),
                    l.dnskey.public_key().public_bytes().to_vec(),
                ))),
            ),
            serial,
        );
        ds.push(d);
    }

    // NSEC chain over every owner name, in canonical order
    let mut types: BTreeMap<Name, BTreeSet<RecordType>> = BTreeMap::new();
    for k in sets.keys() {
        types
            .entry(Name::from(k.name.clone()))
            .or_default()
            .insert(k.record_type);
    }
    let order: Vec<Name> = types.keys().cloned().collect();
    for (i, name) in order.iter().enumerate() {
        let next = order
            .get((i + 1) % order.len())
            .cloned()
            .unwrap_or_else(|| apex.clone());
        let have = types.get(name).cloned().unwrap_or_default();
        let nsec = NSEC::new_cover_self(next, have);
        add(
            &mut sets,
            Record::from_rdata(
                name.clone(),
                id.soa_minimum,
                RData::DNSSEC(DNSSECRData::NSEC(nsec)),
            ),
            serial,
        );
    }

    // signatures
    let inception_ts = now.saturating_sub(t.inception_skew);
    let inception =
        OffsetDateTime::from_unix_timestamp(i64::try_from(inception_ts).map_err(sign_err)?)
            .map_err(sign_err)?;
    let duration = Duration::from_secs(t.sig_validity + t.inception_skew);
    let ksk_signers: Vec<DnssecSigner> =
        ksks.iter().map(|l| signer_for(l, apex, duration)).collect();
    let zsk_signer = {
        let (_, l) = zsks
            .iter()
            .find(|(g, _)| *g == active_gen)
            .ok_or(BuildError::Key(KeyError::Unavailable))?;
        signer_for(l, apex, duration)
    };
    for set in sets.values_mut() {
        set.clear_rrsigs();
        let key_set = matches!(
            set.record_type(),
            RecordType::DNSKEY | RecordType::CDS | RecordType::CDNSKEY
        );
        let signers: Vec<&DnssecSigner> = if key_set {
            ksk_signers.iter().collect()
        } else {
            vec![&zsk_signer]
        };
        for s in signers {
            let rrsig = RRSIG::from_rrset(set, DNSClass::IN, inception, s).map_err(sign_err)?;
            let name = set.name().clone();
            let ttl = set.ttl();
            set.insert_rrsig(Record::from_rdata(
                name,
                ttl,
                RData::DNSSEC(DNSSECRData::RRSIG(rrsig)),
            ));
        }
    }

    let expiry = now.saturating_add(t.sig_validity);
    let refresh_at = expiry
        .saturating_sub(t.refresh_before)
        .min(next_schedule_event(&policy, t, now));
    Ok(SignedZone {
        origin: apex.clone(),
        records: sets,
        serial,
        signed: true,
        refresh_at,
        earliest_expiry: expiry,
        ds,
    })
}
